using FluentValidation;
using MediatR;
using SBRS.Application.Common.Exceptions;
using SBRS.Application.Features.Facilities.DTOs;
using SBRS.Application.Features.Facilities.Mappings;
using SBRS.Domain.Common;
using SBRS.Domain.Entities;
using SBRS.Domain.Exceptions;
using SBRS.Domain.Interfaces;
using System.Net;

namespace SBRS.Application.Features.Facilities.Commands;

// No Code here: it is generated by the system as {CityCCode}-{FacilityTypeCode}-{Sequence}.
public record AddFacilityCommand(Guid BranchId, Guid AddressId, Guid typeId, Guid PartnerId, string? ProjectCode, DateOnly StartDate, string ArName, string EnName)
    : IRequest<FacilityDto>;

public class AddFacilityCommandValidator : AbstractValidator<AddFacilityCommand>
{
    public AddFacilityCommandValidator()
    {
        RuleFor(x => x.BranchId).NotEmpty();
        RuleFor(x => x.AddressId).NotEmpty();
        RuleFor(x => x.ArName).NotEmpty().MaximumLength(200);
        RuleFor(x => x.EnName).NotEmpty().MaximumLength(200);
        RuleFor(x => x.typeId).NotEmpty();
        RuleFor(x => x.PartnerId).NotEmpty();
        RuleFor(x => x.StartDate).NotEmpty();
    }
}

public class AddFacilityCommandHandler(
    IFacilityRepository facilities,
    IBranchRepository branches,
    IAddressRepository addresses,
    IUnitOfWork unitOfWork,
    IPartnerRepository partners,
    IFacilityPartnerRepository history,
    IGeographyRepository geography,
    IFacilityTypeRepository facilityTypes
    )
    : IRequestHandler<AddFacilityCommand, FacilityDto>
{
    private const int MaxCodeAttempts = 3;

    public async Task<FacilityDto> Handle(AddFacilityCommand request, CancellationToken ct)
    {
        var partner = await partners.GetByIdAsync(request.PartnerId, ct)
              ?? throw new NotFoundException(nameof(PartnerEntity), request.PartnerId);
        // scoped lookup: an OrganizationAdmin cannot add a facility to another organization's branch
        var branch = await branches.GetByIdAsync(request.BranchId, ct)
                     ?? throw new NotFoundException(nameof(BranchEntity), request.BranchId);

        if (!branch.IsActive)
            throw new DomainException("Cannot add a facility to a deactivated branch.");

        var address = await addresses.GetByIdAsync(request.AddressId, ct)
                      ?? throw new NotFoundException(nameof(AddressEntity), request.AddressId);

        if (!address.IsActive)
            throw new DomainException("Cannot use a deactivated address.");

        var facilityType = await facilityTypes.GetByIdAsync(request.typeId, ct)
                           ?? throw new NotFoundException(nameof(FacilityTypeEntity), request.typeId);

        if (string.IsNullOrWhiteSpace(facilityType.Code))
            throw new ConflictException("The facility type has no code, so a facility code cannot be generated.");

        // the facility's city is the city of its address: address -> area -> city
        var area = await geography.GetAreaByIdAsync(address.AreaId, ct)
                   ?? throw new NotFoundException(nameof(AreaEntity), address.AreaId);

        var city = await geography.GetCityByIdAsync(area.CityId, ct)
                   ?? throw new NotFoundException(nameof(CityEntity), area.CityId);

        if (string.IsNullOrWhiteSpace(city.C_Code))
            throw new ConflictException($"The city '{city.EnName}' has no c_code, so a facility code cannot be generated.");

        // The code is generated here and is immutable afterwards: it is never recomputed on edit,
        // because beneficiary FullCodes are built from it.
        // Creation is rare, so there is no counter column: the next sequence is the current
        // facility count in the city + 1. A UNIQUE index on facilities.code guards against
        // two admins creating a facility in the same city at the same moment; on a unique
        // violation we re-read the count and retry, until max attempts, then 409 Conflict.
        for (var attempt = 1; attempt <= MaxCodeAttempts; attempt++)
        {
            var next = await facilities.CountByCityAsync(city.Id, ct) + 1;
            var code = FacilityCodeBuilder.Build(city.C_Code, facilityType.Code, next);

            // cheap pre-check for a persistent collision (e.g. a legacy code); a race is caught by the unique index below
            if (await facilities.CodeExistsAsync(code, null, ct))
                continue;

            var facility = new FacilityEntity(branch.Id, address.Id, request.typeId, request.PartnerId, request.ArName, request.EnName, code);

            await facilities.AddAsync(facility, ct);

            var facilityPartner = new FacilityPartnerEntity(facility, partner, request.StartDate, request.ProjectCode);
            await history.AddAsync(facilityPartner, ct);

            try
            {
                await unitOfWork.SaveChangesAsync(ct);
            }
            catch (UniqueViolationException)
            {
                // someone else saved a facility with the same code between the count and the save:
                // drop the staged rows and re-read the count on the next attempt
                facilities.RemoveStaged(facility);
                history.RemoveStaged(facilityPartner);

                if (attempt == MaxCodeAttempts)
                    throw new ConflictException(
                        $"Could not generate a unique facility code for city '{city.C_Code}' after {MaxCodeAttempts} attempts.");

                continue;
            }

            return facility.ToDto();
        }

        // unreachable: the loop either returns or throws
        throw new ConflictException(
            $"Could not generate a unique facility code for city '{city.C_Code}' after {MaxCodeAttempts} attempts.");
    }
}
